import sys, itertools
data=[]
for l in open(sys.argv[1]):
    p,s=l.split()
    if len(set(s))==len(s): data.append((s,p=='P'))
B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
def bits_ascii(s): return ''.join(format(ord(c),'08b') for c in s)
def bits_nib(s): return ''.join(format(int(c,16),'04b') for c in s)
def bits_b64(s): return ''.join(format(B64.index(c),'06b') for c in s)
def bits_dec(s): return format(int(s),'b')
def bits_b62(s):
    A='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
    v=0
    for c in s: v=v*62+A.index(c)
    return format(v,'b')
def bits_b10rev(s): return format(int(s[::-1]),'b')
maps={'ascii':bits_ascii,'nib':bits_nib,'b64':bits_b64,'dec':bits_dec,'b62':bits_b62,'decrev':bits_b10rev}
def stats(b):
    d={}
    d['ones']=b.count('1')
    d['runs']=1+sum(1 for i in range(len(b)-1) if b[i]!=b[i+1])
    d['lr1']=max(len(x) for x in b.split('0'))
    d['lr0']=max(len(x) for x in b.split('1'))
    for pat in ['00','01','10','11']:
        d['s'+pat]=sum(1 for i in range(len(b)-1) if b[i:i+2]==pat)
    d['len']=len(b)
    return d
for mname,m in maps.items():
    rows=[(stats(m(s)),p) for s,p in data]
    for key in rows[0][0]:
        P=sorted(r[key] for r,p in rows if p)
        F=sorted(r[key] for r,p in rows if not p)
        # check separability by threshold
        if P[-1]<F[0] or F[-1]<P[0]:
            print("SEPARABLE",mname,key,P[0],P[-1],F[0],F[-1])
        else:
            # overlap degree
            pass
    print(mname,'done')
