    if(strchr(mode,'N')) { snprintf(key,64,"bias%d",n); ADD(key,1);} 
    ADD("bias",1);
    Row*r=&rows[nrows++]; r->nf=nf; r->idx=malloc(nf*sizeof(int)); r->val=malloc(nf); memcpy(r->idx,tmpi,nf*sizeof(int)); memcpy(r->val,tmpv,nf); r->y= line[0]=='P'?1:-1;
  }
