#define HS (1<<20)
static int htab[HS];
static unsigned hashs(const char*s){unsigned h=2166136261u; while(*s){h^=(unsigned char)*s++; h*=16777619u;} return h;}
int fid(const char*s){ unsigned h=hashs(s)&(HS-1); while(htab[h]){ if(!strcmp(names[htab[h]-1],s)) return htab[h]-1; h=(h+1)&(HS-1);} names[nnames]=strdup(s); htab[h]=nnames+1; return nnames++; }
int main(int argc,char**argv){
  const char*mode=argv[1]; int iters=atoi(argv[2]); double lambda=atof(argv[3]);
  static Row rows[MAXROWS]; int nrows=0;
