    int n=strlen(s); int nf=0; char key[64];
    #define ADD(k,v) do{ int id=fid(k); int found=-1; for(int q=0;q<nf;q++) if(tmpi[q]==id){found=q;break;} if(found>=0) tmpv[found]+=v; else {tmpi[nf]=id; tmpv[nf]=v; nf++;} }while(0)
    if(strchr(mode,'b')) for(int i=0;i<n-1;i++){ snprintf(key,64,"b%c%c",s[i],s[i+1]); ADD(key,1);} 
    if(strchr(mode,'u')) for(int i=0;i<n;i++){ snprintf(key,64,"u%c",s[i]); ADD(key,1);} 
    if(strchr(mode,'f')) { snprintf(key,64,"first%c",s[0]); ADD(key,1); snprintf(key,64,"last%c",s[n-1]); ADD(key,1);} 
    if(strchr(mode,'d')) { int seen[256]={0},D=0; for(int i=0;i<n;i++){ if(!seen[(unsigned char)s[i]]){seen[(unsigned char)s[i]]=1;D++;} } snprintf(key,64,"dist%d_%d",n,D); ADD(key,1);} 
    if(strchr(mode,'N')) { snprintf(key,64,"bias%d",n); ADD(key,1);} 
    ADD("bias",1);
    Row*r=&rows[nrows++]; r->nf=nf; r->idx=malloc(nf*sizeof(int)); r->val=malloc(nf); memcpy(r->idx,tmpi,nf*sizeof(int)); memcpy(r->val,tmpv,nf); r->y= line[0]=='P'?1:-1; strncpy(r->s,s,15);
  }
  fprintf(stderr,"rows %d feats %d\n",nrows,nnames);
  double *w=calloc(nnames,sizeof(double));
  srand(1); long t=1;
  for(int it=0;it<iters;it++){
    int err=0;
    for(int q=0;q<nrows;q++){ Row*r=&rows[rand()%nrows]; double eta=1.0/(lambda*t); t++;
      double d=0; for(int k=0;k<r->nf;k++) d+=w[r->idx[k]]*r->val[k];
      for(int i=0;i<nnames;i++) w[i]*= (1-eta*lambda);
      if(r->y*d<1){ for(int k=0;k<r->nf;k++) w[r->idx[k]]+=eta*r->y*r->val[k]; }
    }
    for(int q=0;q<nrows;q++){ Row*r=&rows[q]; double d=0; for(int k=0;k<r->nf;k++) d+=w[r->idx[k]]*r->val[k]; if(r->y*d<=0) err++; }
    fprintf(stderr,"iter %d errors %d\n",it,err);
  }
  for(int i=0;i<nnames;i++) printf("%s %.4f\n",names[i],w[i]);
  return 0;
}
