{"command":"cd /workspace && cat > src/p_random.rs <<'EOF'
//! Heuristic estimate of the probability that a string was randomly generated.
//!
//! The estimate combines several independent-ish observations about the string:
//!   * how many distinct characters it has compared to a uniformly random
//!     string drawn from the inferred alphabet,
//!   * how the character classes (digits / lowercase / uppercase / other) are
//!     distributed compared to the inferred alphabet,
//!   * (for general alphabets) how "text like" its character bigrams are,
//!     according to a bigram table trained on source code.
//! The product of these p-values is compared against a fixed threshold.

use crate::bigram_table::{BIGRAM_COUNTS, BIGRAM_N, BIGRAM_TOTAL};
use std::sync::OnceLock;

/// Strings with an estimated probability below this are considered not random.
pub const RANDOM_THRESHOLD: f64 = 1e-5;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Alphabet {
    Hex,
    UpperDigits,
    General,
}

struct ClassCounts {
    digits: usize,
    lower: usize,
    upper: usize,
    other: usize,
}

fn classify(s: &[u8]) -> ClassCounts {
    let mut c = ClassCounts { digits: 0, lower: 0, upper: 0, other: 0 };
    for &b in s {
        match b {
            b'0'..=b'9' => c.digits += 1,
            b'a'..=b'z' => c.lower += 1,
            b'A'..=b'Z' => c.upper += 1,
            _ => c.other += 1,
        }
    }
    c
}

fn infer_alphabet(s: &[u8], c: &ClassCounts) -> Alphabet {
    if s.len() >= 16 && c.other == 0 {
        let lower_hex = s.iter().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(b));
        let upper_hex = s.iter().all(|b| b.is_ascii_digit() || (b'A'..=b'F').contains(b));
        if lower_hex || upper_hex {
            return Alphabet::Hex;
        }
        if c.lower == 0 {
            return Alphabet::UpperDigits;
        }
    }
    Alphabet::General
}

fn distinct_count(s: &[u8]) -> usize {
    let mut seen = [false; 256];
    let mut d = 0;
    for &b in s {
        if !seen[b as usize] {
            seen[b as usize] = true;
            d += 1;
        }
    }
    d
}

/// Probability that a uniformly random string of length `n` over an alphabet
/// of size `k` has at most `d` distinct characters.
fn p_distinct(n: usize, d: usize, k: usize) -> f64 {
    if d >= k.min(n) {
        return 1.0;
    }
    let n = n.min(2048);
    // dist[j] = P(exactly j distinct after i characters)
    let mut dist = vec![0.0f64; k + 2];
    dist[1] = 1.0;
    let kf = k as f64;
    for _ in 1..n {
        let mut next = vec![0.0f64; k + 2];
        for j in 1..=k {
            let p = dist[j];
            if p == 0.0 {
                continue;
            }
            // repeat one of the j seen characters
            next[j] += p * (j as f64 / kf);
            // see a new character
            if j < k {
                next[j + 1] += p * ((k - j) as f64 / kf);
            }
        }
        dist = next;
    }
    let mut acc = 0.0;
    for j in 1..=d.min(k) {
        acc += dist[j];
    }
    acc.min(1.0).max(1e-300)
}

fn ln_choose(n: usize, k: usize) -> f64 {
    ln_factorial(n) - ln_factorial(k) - ln_factorial(n - k)
}

fn ln_factorial(n: usize) -> f64 {
    static TABLE: OnceLock<Vec<f64>> = OnceLock::new();
    let table = TABLE.get_or_init(|| {
        let mut v = vec![0.0f64; 4096];
        for i in 1..v.len() {
            v[i] = v[i - 1] + (i as f64).ln();
        }
        v
    });
    if n < table.len() {
        table[n]
    } else {
        // Stirling approximation
        let x = n as f64;
        x * x.ln() - x + 0.5 * (2.0 * std::f64::consts::PI * x).ln()
    }
}

fn binom_pmf(n: usize, k: usize, p: f64) -> f64 {
    if p <= 0.0 {
        return if k == 0 { 1.0 } else { 0.0 };
    }
    if p >= 1.0 {
        return if k == n { 1.0 } else { 0.0 };
    }
    (ln_choose(n, k) + k as f64 * p.ln() + (n - k) as f64 * (1.0 - p).ln()).exp()
}

/// min(P(X <= x), P(X >= x)) for X ~ Binomial(n, p)
fn binom_tail(n: usize, x: usize, p: f64) -> f64 {
    let mut le = 0.0;
    for i in 0..=x {
        le += binom_pmf(n, i, p);
    }
    let mut ge = 0.0;
    for i in x..=n {
        ge += binom_pmf(n, i, p);
    }
    le.min(ge).min(1.0).max(1e-300)
}

fn p_classes(n: usize, counts: &[(usize, usize)], k: usize) -> f64 {
    let mut p = 1.0f64;
    for &(obs, size) in counts {
        let t = binom_tail(n, obs, size as f64 / k as f64);
        if t < p {
            p = t;
        }
    }
    p
}

struct BigramModel {
    logp: Vec<f64>, // joint log probability of each bigram (N*N)
    mean: f64,      // mean of logp under uniform random pairs
    sd: f64,        // standard deviation under uniform random pairs
}

fn bigram_model() -> &'static BigramModel {
    static MODEL: OnceLock<BigramModel> = OnceLock::new();
    MODEL.get_or_init(|| {
        let n = BIGRAM_N;
        let total = BIGRAM_TOTAL as f64 + (n * n) as f64;
        let mut logp = Vec::with_capacity(n * n);
        for row in BIGRAM_COUNTS.iter() {
            for &c in row.iter() {
                logp.push(((c as f64 + 1.0) / total).ln());
            }
        }
        let m = logp.iter().sum::<f64>() / logp.len() as f64;
        let var = logp.iter().map(|v| (v - m) * (v - m)).sum::<f64>() / logp.len() as f64;
        BigramModel { logp, mean: m, sd: var.sqrt().max(1e-9) }
    })
}

fn norm_cdf(z: f64) -> f64 {
    0.5 * (1.0 + erf(z / std::f64::consts::SQRT_2))
}

fn erf(x: f64) -> f64 {
    // Abramowitz & Stegun 7.1.26 with refinement for the tails
    let t = 1.0 / (1.0 + 0.3275911 * x.abs());
    let y = 1.0
        - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t
            + 0.254829592)
            * t
            * (-x * x).exp();
    if x >= 0.0 { y } else { -y }
}

/// Probability that a random string would look at least as "text like" as `s`.
fn p_bigrams(s: &[u8]) -> f64 {
    if s.len() < 2 {
        return 1.0;
    }
    let model = bigram_model();
    let idx = |b: u8| -> Option<usize> {
        if (33..=126).contains(&b) { Some(b as usize - 33) } else { None }
    };
    let mut sum = 0.0;
    let mut m = 0usize;
    for w in s.windows(2) {
        if let (Some(a), Some(b)) = (idx(w[0]), idx(w[1])) {
            sum += model.logp[a * BIGRAM_N + b];
            m += 1;
        }
    }
    if m == 0 {
        return 1.0;
    }
    let z = (sum - m as f64 * model.mean) / (model.sd * (m as f64).sqrt());
    // Large z means the bigrams are much more common in text than expected
    // for random data.
    (1.0 - norm_cdf(z)).max(1e-300)
}

/// Estimate the probability that `s` is a randomly generated string.
pub fn p_random(s: &[u8]) -> f64 {
    let n = s.len();
    if n == 0 {
        return 1.0;
    }
    let c = classify(s);
    let d = distinct_count(s);
    match infer_alphabet(s, &c) {
        Alphabet::Hex => {
            let letters = n - c.digits;
            // the class distribution of long hex strings is judged on a
            // fixed sized window
            let m = n.min(16);
            let scaled = ((letters as f64) * (m as f64) / (n as f64)).round() as usize;
            p_distinct(n, d, 16) * p_classes(m, &[(scaled.min(m), 6)], 16)
        }
        Alphabet::UpperDigits => {
            p_distinct(n, d, 36) * p_classes(n, &[(c.digits, 10), (c.upper, 26)], 36)
        }
        Alphabet::General => {
            let classes = [(c.digits, 10), (c.lower, 26), (c.upper, 26), (c.other, 2)];
            p_distinct(n, d, 64) * p_classes(n, &classes, 64) * p_bigrams(s)
        }
    }
}

pub fn is_random(s: &[u8]) -> bool {
    p_random(s) >= RANDOM_THRESHOLD
}
