    // Mailchimp
    r"[0-9a-f]{32}-us[0-9]{1,2}",
    // Credentials embedded in URLs
    r"(?i)[a-z+\-]+://[^\s]{3,}:([^\s]{8,})@[^\s@]",
    // Generic key/secret/token/password assignments
    r#"(?i)(?:key|secret|token|password)\w*["']?\]?\s*(?:=|:|>|:=|=>)\s*["']?([A-Za-z0-9+/=\-_.~^\\`]{15,})(?:["'\t ]|$)"#,
];

pub struct Found {
    pub start: usize,
    pub secret: Vec<u8>,
}

pub struct Matcher {
    patterns: Vec<Pattern>,
}

impl Matcher {
    pub fn new(additional: &[String]) -> Result<Matcher, regex::Error> {
        let mut patterns = Vec::new();
        for p in BUILTIN.iter() {
            let re = Regex::new(p).expect("builtin pattern must compile");
            let test_group = re.captures_len() > 1;
            patterns.push(Pattern { re, test_group });
        }
        for p in additional {
            let re = Regex::new(p)?;
            let test_group = re.captures_len() > 1;
            patterns.push(Pattern { re, test_group });
        }
        Ok(Matcher { patterns })
    }

    /// Find all secrets on a single line (without its terminator), sorted by
    /// their position in the line.
    pub fn find(&self, line: &[u8], ignored: &[Vec<u8>]) -> Vec<Found> {
        let mut out = Vec::new();
        for p in &self.patterns {
            for caps in p.re.captures_iter(line) {
                let m = if p.test_group {
                    match caps.get(1) {
                        Some(g) => g,
                        None => continue,
                    }
                } else {
                    caps.get(0).unwrap()
                };
                let secret = m.as_bytes();
                if p.test_group && !is_random(secret) {
                    continue;
                }
                if ignored.iter().any(|s| s.as_slice() == secret) {
                    continue;
                }
                out.push(Found { start: m.start(), secret: secret.to_vec() });
            }
        }
        out.sort_by_key(|f| f.start);
        out
    }
}
