//! Handling of the `.secretsignore` file in the current directory.
//!
//! The file has two sections: gitignore-like path patterns, and, after a
//! `[secrets]` header, exact secret values that should never be reported.

use globset::{Glob, GlobBuilder, GlobMatcher};
use std::path::Path;

struct IgnorePattern {
    matcher: GlobMatcher,
    negated: bool,
    dir_only: bool,
}

pub struct IgnoreInfo {
    patterns: Vec<IgnorePattern>,
    pub secrets: Vec<Vec<u8>>,
}

impl IgnoreInfo {
    pub fn empty() -> IgnoreInfo {
        IgnoreInfo { patterns: Vec::new(), secrets: Vec::new() }
    }

    pub fn load(path: &Path) -> IgnoreInfo {
        let data = match std::fs::read(path) {
            Ok(d) => d,
            Err(_) => return IgnoreInfo::empty(),
        };
        let mut info = IgnoreInfo::empty();
        let mut in_secrets = false;
        for raw in data.split(|&b| b == b'\n') {
            if raw == b"[secrets]" {
                in_secrets = true;
                continue;
            }
            if in_secrets {
                if !raw.is_empty() {
                    info.secrets.push(raw.to_vec());
                }
                continue;
            }
            let line = match std::str::from_utf8(raw) {
                Ok(l) => l,
                Err(_) => continue,
            };
            if let Some(p) = parse_pattern(line) {
                info.patterns.push(p);
            }
        }
        info
    }

    pub fn has_patterns(&self) -> bool {
        !self.patterns.is_empty()
    }

    /// Whether `path` (relative to the current directory) is excluded by the
    /// path patterns.
    pub fn is_ignored(&self, path: &Path, is_dir: bool) -> bool {
        if self.patterns.is_empty() {
            return false;
        }
        let rel = normalize(path);
        let mut ignored = false;
        for p in &self.patterns {
            if p.dir_only && !is_dir {
                continue;
            }
            if p.matcher.is_match(&rel) {
                ignored = !p.negated;
            }
        }
        ignored
    }

    /// Like `is_ignored`, but also considers every parent directory of `path`.
    pub fn is_ignored_with_parents(&self, path: &Path, is_dir: bool) -> bool {
        if self.is_ignored(path, is_dir) {
            return true;
        }
        let rel = normalize(path);
        let mut cur = Path::new(&rel);
        while let Some(parent) = cur.parent() {
            if parent.as_os_str().is_empty() {
                break;
            }
            if self.is_ignored(parent, true) {
                return true;
            }
            cur = parent;
        }
        false
    }
}

fn normalize(path: &Path) -> String {
    let s = path.to_string_lossy();
    let mut s: &str = &s;
    while let Some(rest) = s.strip_prefix("./") {
        s = rest;
    }
    s.to_string()
}

fn parse_pattern(line: &str) -> Option<IgnorePattern> {
    // gitignore semantics: trailing whitespace is insignificant unless escaped
    let mut line = line.trim_end_matches(|c| c == ' ' || c == '\t' || c == '\r');
    if line.is_empty() || line.starts_with('#') {
