    #[arg(long = "additional-pattern", value_name = "ADDITIONAL_PATTERNS")]
    additional_patterns: Vec<String>,

    /// Source files. Can be files or directories. Defaults to '.'
    #[arg(value_name = "Source files")]
    paths: Vec<PathBuf>,
}

const PRE_COMMIT_LINE: &str =
    "ripsecrets --strict-ignore `git diff --cached --name-only --diff-filter=ACM`\n";

fn install_pre_commit(paths: &[PathBuf]) -> Result<(), String> {
    for path in paths {
        let git_dir = path.join(".git");
        if !git_dir.exists() {
            return Err(".git directory not found".to_string());
        }
        let hook = git_dir.join("hooks").join("pre-commit");
        if hook.exists() {
            let contents = std::fs::read_to_string(&hook).map_err(|e| e.to_string())?;
            if contents.contains("ripsecrets") {
                return Err("pre-commit hook has already been installed".to_string());
            }
            let mut f = std::fs::OpenOptions::new()
                .append(true)
                .open(&hook)
                .map_err(|e| e.to_string())?;
            f.write_all(PRE_COMMIT_LINE.as_bytes()).map_err(|e| e.to_string())?;
        } else {
            use std::os::unix::fs::OpenOptionsExt;
            let mut f = std::fs::OpenOptions::new()
                .write(true)
                .create(true)
                .mode(0o744)
                .open(&hook)
                .map_err(|e| e.to_string())?;
            f.write_all(PRE_COMMIT_LINE.as_bytes()).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

/// Decode UTF-16 (with BOM) content into UTF-8; leave everything else alone.
fn normalize_encoding(data: Vec<u8>) -> Vec<u8> {
    let (le, be) = (data.starts_with(&[0xFF, 0xFE]), data.starts_with(&[0xFE, 0xFF]));
    if !le && !be {
        return data;
    }
    let body = &data[2..];
    let units: Vec<u16> = body
        .chunks(2)
        .map(|c| {
            let (a, b) = (c[0] as u16, *c.get(1).unwrap_or(&0) as u16);
            if le { a | (b << 8) } else { (a << 8) | b }
        })
        .collect();
    let mut out = String::new();
    for r in char::decode_utf16(units) {
        out.push(r.unwrap_or(char::REPLACEMENT_CHARACTER));
    }
    out.into_bytes()
}

struct Scanner {
    matcher: Matcher,
    ignored_secrets: Vec<Vec<u8>>,
    only_matching: bool,
    found: AtomicBool,
    stdout: Mutex<()>,
}

impl Scanner {
    fn scan_file(&self, path: &Path) {
        let data = match std::fs::read(path) {
            Ok(d) => d,
            Err(e) => {
                eprintln!("{}: {}", path.display(), e);
                return;
            }
        };
        let data = normalize_encoding(data);
        let mut out: Vec<u8> = Vec::new();
        let display = path.display().to_string();
        let mut lineno = 0usize;
        let mut rest: &[u8] = &data;
        while !rest.is_empty() {
            lineno += 1;
            let (line, next) = match rest.iter().position(|&b| b == b'\n') {
                Some(i) => (&rest[..i], &rest[i + 1..]),
                None => (rest, &rest[rest.len()..]),
            };
            rest = next;
            if line.is_empty() {
                continue;
            }
            let found = self.matcher.find(line, &self.ignored_secrets);
            if found.is_empty() {
                continue;
            }
            if self.only_matching {
                for f in &found {
                    out.extend_from_slice(format!("{}:{}:", display, lineno).as_bytes());
                    out.extend_from_slice(&f.secret);
                    out.push(b'\n');
                }
            } else {
                out.extend_from_slice(format!("{}:{}:", display, lineno).as_bytes());
                out.extend_from_slice(line);
                out.push(b'\n');
            }
        }
        if out.is_empty() {
            return;
        }
        self.found.store(true, Ordering::SeqCst);
        let _guard = self.stdout.lock().unwrap();
        let stdout = std::io::stdout();
        let mut handle = stdout.lock();
        if let Err(e) = handle.write_all(&out).and_then(|_| handle.flush()) {
            eprintln!("{}: {}", display, e);
        }
    }
}

fn main() {
    let args = Args::parse();
    let paths: Vec<PathBuf> = if args.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.paths.clone()
    };

    if args.install_pre_commit {
        if let Err(e) = install_pre_commit(&paths) {
            eprintln!("Error: {}", e);
            std::process::exit(2);
        }
        return;
    }

    let matcher = match Matcher::new(&args.additional_patterns) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(2);
        }
    };

    let ignore_info = Arc::new(IgnoreInfo::load(Path::new(".secretsignore")));
    let scanner = Arc::new(Scanner {
        matcher,
        ignored_secrets: ignore_info.secrets.clone(),
        only_matching: args.only_matching,
        found: AtomicBool::new(false),
        stdout: Mutex::new(()),
    });

    let mut builder = WalkBuilder::new(&paths[0]);
    for p in &paths[1..] {
        builder.add(p);
    }
    let strict = args.strict_ignore;
    if ignore_info.has_patterns() {
        let info = ignore_info.clone();
        builder.filter_entry(move |entry: &DirEntry| {
            let is_dir = entry.file_type().map_or(false, |ft| ft.is_dir());
            if entry.depth() == 0 {
                !(strict && info.is_ignored_with_parents(entry.path(), is_dir))
            } else {
                !info.is_ignored(entry.path(), is_dir)
            }
        });
    }

    builder.build_parallel().run(|| {
        let scanner = scanner.clone();
        Box::new(move |result| {
            match result {
                Ok(entry) => {
                    if entry.file_type().map_or(false, |ft| ft.is_file()) {
                        scanner.scan_file(entry.path());
                    }
                }
                Err(err) => {
                    eprintln!("{}", err);
                }
            }
            WalkState::Continue
        })
    });

    if scanner.found.load(Ordering::SeqCst) {
        std::process::exit(1);
    }
}
